export function PricingTier({
  planName = "{{planName}}",
  price = "{{price}}",
  period = "{{period}}",
  accent = "{{accent}}",
  highlighted = {{highlighted}},
}) {
  return (
    <div style={{
      position: "relative", maxWidth: 280, padding: "24px 20px", background: "#FAF7F2", color: "#241430",
      fontFamily: "system-ui, sans-serif", border: `1.5px solid ${accent}`, borderRadius: 16,
      boxShadow: highlighted ? "0 8px 24px rgba(36,20,48,.16)" : "none",
      transform: highlighted ? "translateY(-4px)" : "none",
    }}>
      {highlighted && (
        <span style={{ position: "absolute", top: -12, right: 20, background: accent, color: "#241430",
          fontSize: 11, fontWeight: 600, padding: "4px 10px", borderRadius: 999 }}>
          Most popular
        </span>
      )}
      <h3 style={{ margin: "0 0 8px", fontSize: 16, fontWeight: 600 }}>{planName}</h3>
      <p style={{ margin: "0 0 16px", fontSize: 32, fontWeight: 700 }}>
        {price}<span style={{ fontSize: 14, fontWeight: 400, color: "#241430aa" }}>/{period}</span>
      </p>
      <ul style={{ listStyle: "none", margin: "0 0 20px", padding: 0, fontSize: 14, color: "#241430cc", display: "grid", gap: 8 }}>
        <li>Unlimited projects</li>
        <li>Priority support</li>
        <li>Team collaboration</li>
      </ul>
      <button type="button" style={{ width: "100%", padding: "10px", borderRadius: 8, border: `1.5px solid ${accent}`,
        background: "transparent", color: "#241430", fontSize: 14, fontWeight: 600, cursor: "pointer" }}>
        Choose {planName}
      </button>
    </div>
  );
}
